const body = $input.first().json.body;

const to = body.to || '';
const directorName = body.directorName || 'R\u00e9alisateur';
const eventId = body.eventId || '';
const eventTitle = body.eventTitle || '';
const eventDate = body.eventDate || '';
const location = body.location || '';
const room = body.room || '';
const regie = body.regie || '';
const recordingLocalPath = body.recordingLocalPath || '';
const conferences = Array.isArray(body.conferences) ? body.conferences : [];
const notes = body.notes || '';

// Format date FR
function formatDate(d) {
  try {
    const dt = new Date(d);
    return dt.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  } catch (e) { return d; }
}

function formatTime(d) {
  if (!d) return '';
  try {
    const dt = new Date(d);
    return dt.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
  } catch (e) { return ''; }
}

const dateStr = formatDate(eventDate);
const subject = `Feuille de route — ${eventTitle} — ${eventId}`;

// Build conferences table rows
let confRows = '';
if (conferences.length === 0) {
  confRows = '<tr><td colspan="4" style="padding:16px;text-align:center;color:#727485;font-style:italic;">Aucune conf\u00e9rence planifi\u00e9e</td></tr>';
} else {
  conferences.forEach((c, idx) => {
    const start = formatTime(c.scheduledStart);
    const end = formatTime(c.scheduledEnd);
    const horaire = (start && end) ? `${start} \u2013 ${end}` : (start || end || '\u2014');
    const bg = idx % 2 === 0 ? '#ffffff' : '#fafbfc';
    confRows += `
      <tr style="background-color:${bg};">
        <td style="padding:12px;border-bottom:1px solid #e5e5e5;font-weight:bold;color:#1f2244;text-align:center;">${c.order || (idx + 1)}</td>
        <td style="padding:12px;border-bottom:1px solid #e5e5e5;color:#1f2244;"><strong>${c.title || ''}</strong>${c.speaker ? `<br><span style=\"color:#727485;font-size:13px;\">${c.speaker}</span>` : ''}</td>
        <td style="padding:12px;border-bottom:1px solid #e5e5e5;color:#727485;font-size:14px;text-align:center;">${horaire}</td>
      </tr>`;
  });
}

const notesBlock = notes.trim() ? `
  <tr>
    <td style="padding:0 30px 24px 30px;">
      <h3 style="color:#1f2244;margin:0 0 8px 0;font-size:15px;">Notes</h3>
      <p style="color:#333333;font-size:14px;line-height:1.6;margin:0;padding:12px 16px;background-color:#fff8e1;border-left:3px solid #f59e0b;border-radius:4px;">${notes.replace(/\n/g, '<br>')}</p>
    </td>
  </tr>` : '';

const pathBlock = recordingLocalPath ? `<tr><td style="padding:8px 0;color:#727485;font-size:13px;">Dossier local</td><td style="padding:8px 0;color:#1f2244;font-size:13px;font-family:monospace;text-align:right;">${recordingLocalPath}</td></tr>` : '';

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Feuille de route — ${eventTitle}</title>
</head>
<body style="margin:0;padding:0;font-family:Arial,Helvetica,sans-serif;background-color:#f5f5f7;">
  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#f5f5f7;padding:40px 20px;">
    <tr>
      <td align="center">
        <table width="640" cellpadding="0" cellspacing="0" border="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.05);">
          <tr>
            <td style="background-color:#1f2244;padding:30px;text-align:center;">
              <h1 style="color:#ffffff;margin:0;font-size:26px;font-weight:bold;letter-spacing:2px;">EVA FLOW</h1>
              <p style="color:#7dcef5;margin:8px 0 0 0;font-size:13px;">Feuille de route</p>
            </td>
          </tr>
          <tr>
            <td style="padding:30px;">
              <p style="color:#1f2244;font-size:16px;margin:0 0 8px 0;">Bonjour <strong>${directorName}</strong>,</p>
              <p style="color:#333333;font-size:15px;line-height:1.6;margin:0 0 24px 0;">
                Vous \u00eates valid\u00e9(e) sur l'\u00e9v\u00e9nement suivant. Voici votre feuille de route :
              </p>
              <div style="background-color:#7dcef5;color:#1f2244;padding:6px 12px;display:inline-block;border-radius:4px;font-family:monospace;font-weight:bold;font-size:14px;margin-bottom:16px;">
                ${eventId}
              </div>
              <h2 style="color:#1f2244;margin:0 0 24px 0;font-size:22px;">${eventTitle}</h2>
              <table width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-bottom:24px;">
                <tr><td style="padding:8px 0;color:#727485;font-size:13px;">Date</td><td style="padding:8px 0;color:#1f2244;font-size:14px;font-weight:bold;text-align:right;">${dateStr}</td></tr>
                <tr><td style="padding:8px 0;color:#727485;font-size:13px;">Lieu</td><td style="padding:8px 0;color:#1f2244;font-size:14px;text-align:right;">${location}</td></tr>
                <tr><td style="padding:8px 0;color:#727485;font-size:13px;">Salle</td><td style="padding:8px 0;color:#1f2244;font-size:14px;text-align:right;">${room}</td></tr>
                ${regie ? `<tr><td style="padding:8px 0;color:#727485;font-size:13px;">R\u00e9gie</td><td style="padding:8px 0;color:#1f2244;font-size:14px;font-weight:bold;text-align:right;">${regie}</td></tr>` : ''}
                ${pathBlock}
              </table>
            </td>
          </tr>
          <tr>
            <td style="padding:0 30px 24px 30px;">
              <h3 style="color:#1f2244;margin:0 0 12px 0;font-size:16px;">Conf\u00e9rences \u00e0 capter (${conferences.length})</h3>
              <table width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid #e5e5e5;border-radius:6px;overflow:hidden;">
                <thead>
                  <tr style="background-color:#1f2244;">
                    <th style="padding:10px;color:#ffffff;font-size:12px;text-align:center;font-weight:bold;width:40px;">#</th>
                    <th style="padding:10px;color:#ffffff;font-size:12px;text-align:left;font-weight:bold;">Conf\u00e9rence</th>
                    <th style="padding:10px;color:#ffffff;font-size:12px;text-align:center;font-weight:bold;width:120px;">Horaire</th>
                  </tr>
                </thead>
                <tbody>
                  ${confRows}
                </tbody>
              </table>
            </td>
          </tr>
          ${notesBlock}
          <tr>
            <td style="padding:0 30px 30px 30px;">
              <p style="color:#727485;font-size:13px;line-height:1.6;margin:0;padding:16px;background-color:#f5f5f7;border-radius:6px;border-left:3px solid #7dcef5;">
                <strong>R\u00e9gie hors ligne ?</strong> Notez l'identifiant <code style="background:#fff;padding:2px 6px;border-radius:3px;font-weight:bold;">${eventId}</code> et le titre de l'\u00e9v\u00e9nement. Vous pourrez les ressaisir sur EVA Capture, et la synchronisation se fera au retour de la connexion.
              </p>
            </td>
          </tr>
          <tr>
            <td style="background-color:#f5f5f7;padding:20px 30px;text-align:center;border-top:1px solid #e5e5e5;">
              <p style="color:#727485;font-size:12px;margin:0;">
                Les Ateliers du Stream &middot; EVA Flow<br>
                <a href="https://evaremote.com" style="color:#727485;text-decoration:none;">evaremote.com</a>
              </p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;

return [{
  json: {
    to: to,
    subject: subject,
    html: html
  }
}];

const emailResult = $input.first().json;

return [{
  json: {
    success: true,
    message_id: emailResult.id || '',
    thread_id: emailResult.threadId || ''
  }
}];
